using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad] public static class WeaponShopBuilder {
 const string Art="Assets/Scripts/Mok/Art/Weapons/",Res="Assets/Resources/MokWeapons/";
 static Material wood,metal,dark,orange,cream,blue,ice,red,skin;
 static WeaponShopBuilder(){EditorApplication.update+=Poll;}
 static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/Mok-weapon-build"))return;File.Delete("Temp/Mok-weapon-build");try{Run();}catch(Exception e){File.WriteAllText("Temp/Mok-weapon-build.txt",e.ToString());Debug.LogException(e);}}
 static Material Mat(string n,Color c){string p=Art+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,p);}m.color=c;m.SetFloat("_Smoothness",.22f);return m;}
 static GameObject Part(Transform parent,string n,Vector3 pos,Vector3 size,Material mat,PrimitiveType shape=PrimitiveType.Cube,bool solid=false){var g=GameObject.CreatePrimitive(shape);g.name=n;g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;if(!solid)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static void MeshPart(Transform parent,string n,Vector3[] vertices,int[] triangles,Material mat){var mesh=new Mesh{name=n};mesh.vertices=vertices;mesh.triangles=triangles;mesh.RecalculateNormals();mesh.RecalculateBounds();string path=Art+n+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing!=null){EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;}else AssetDatabase.CreateAsset(mesh,path);var go=new GameObject(n,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(parent,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=mat;}
 static void Lathe(Transform p,string n,float[] heights,float[] radii,float depth,Material mat){var v=new List<Vector3>();var tri=new List<int>();const int count=12;for(int j=0;j<heights.Length;j++)for(int i=0;i<count;i++){float a=i*Mathf.PI*2/count;v.Add(new Vector3(Mathf.Cos(a)*radii[j],heights[j],Mathf.Sin(a)*radii[j]*depth));}for(int j=0;j<heights.Length-1;j++)for(int i=0;i<count;i++){int a=j*count+i,b=j*count+(i+1)%count,c=a+count,d=b+count;tri.AddRange(new[]{a,c,b,b,c,d});}MeshPart(p,n,v.ToArray(),tri.ToArray(),mat);}
 static void Fin(Transform p,string n,Vector3 a,Vector3 b,Vector3 c,Material mat){MeshPart(p,n,new[]{a,b,c,a+Vector3.forward*.035f,b+Vector3.forward*.035f,c+Vector3.forward*.035f},new[]{0,2,1,3,4,5,0,1,4,0,4,3,1,2,5,1,5,4,2,0,3,2,3,5},mat);}
 static void Models(){for(int k=0;k<4;k++){var root=new GameObject(((WeaponKind)k).ToString());var t=root.transform;
 if(k==0){Lathe(t,"Bat turned wood",new[]{0f,.03f,.09f,.34f,.62f,.94f,1.02f,1.05f},new[]{0f,.045f,.024f,.028f,.06f,.075f,.065f,0f},1,wood);for(int i=0;i<7;i++)Part(t,"Grip tape",new Vector3(0,.1f+i*.032f,0),new Vector3(.058f,.014f,.058f),dark,PrimitiveType.Cylinder);Part(t,"Orange band",new Vector3(0,.71f,0),new Vector3(.16f,.025f,.16f),orange,PrimitiveType.Cylinder);}
 if(k==1){Lathe(t,"Frozen tuna body",new[]{0f,.15f,.3f,.5f,.7f,.88f,1f},new[]{0f,.055f,.17f,.22f,.19f,.11f,0f},.65f,blue);Part(t,"Silver belly",new Vector3(0,.55f,-.1f),new Vector3(.29f,.62f,.2f),ice,PrimitiveType.Sphere);Fin(t,"Tuna tail",new Vector3(-.26f,0,0),new Vector3(0,.22f,0),new Vector3(.26f,0,0),blue);Fin(t,"Tuna dorsal",new Vector3(.12f,.39f,0),new Vector3(.37f,.48f,0),new Vector3(.13f,.77f,0),blue);Fin(t,"Tuna left fin",new Vector3(-.12f,.65f,0),new Vector3(-.34f,.38f,0),new Vector3(-.13f,.4f,0),metal);for(int side=-1;side<=1;side+=2){Part(t,"Fish eye",new Vector3(side*.086f,.86f,-.066f),new Vector3(.045f,.045f,.025f),cream,PrimitiveType.Sphere);Part(t,"Pupil",new Vector3(side*.086f,.86f,-.08f),new Vector3(.024f,.024f,.015f),dark,PrimitiveType.Sphere);}for(int i=0;i<4;i++)Part(t,"Frost crystal",new Vector3((i%2==0?1:-1)*.12f,.36f+i*.1f,-.13f),Vector3.one*.035f,ice);}
 if(k==2){Part(t,"Brick body",Vector3.zero,new Vector3(.23f,.11f,.11f),red);for(int i=0;i<3;i++)Part(t,"Brick holes",new Vector3((i-1)*.06f,.056f,0),new Vector3(.035f,.002f,.045f),dark);Part(t,"Chipped edge",new Vector3(.08f,.03f,-.056f),new Vector3(.05f,.028f,.002f),wood);}
 if(k==3){Part(t,"Slide",new Vector3(0,.28f,.07f),new Vector3(.065f,.09f,.25f),metal);var grip=Part(t,"Grip",new Vector3(0,.16f,-.005f),new Vector3(.065f,.19f,.09f),dark);grip.transform.localRotation=Quaternion.Euler(-14,0,0);Part(t,"Barrel muzzle",new Vector3(0,.28f,.198f),new Vector3(.032f,.032f,.012f),dark,PrimitiveType.Cylinder).transform.localRotation=Quaternion.Euler(90,0,0);Part(t,"Trigger guard",new Vector3(0,.18f,.08f),new Vector3(.025f,.025f,.12f),metal);Part(t,"Guard front",new Vector3(0,.21f,.13f),new Vector3(.025f,.08f,.025f),metal);Part(t,"Trigger",new Vector3(0,.22f,.06f),new Vector3(.015f,.05f,.015f),dark);Part(t,"Front sight",new Vector3(0,.334f,.16f),new Vector3(.018f,.022f,.025f),orange);for(int i=0;i<4;i++)Part(t,"Slide serration",new Vector3(.034f,.29f,-.025f+i*.015f),new Vector3(.003f,.05f,.005f),dark);}
 PrefabUtility.SaveAsPrefabAsset(root,Res+((WeaponKind)k)+".prefab");UnityEngine.Object.DestroyImmediate(root);}}
 static void Text(Transform p,string n,Vector3 pos,int size,float scale){var go=new GameObject(n,typeof(TextMesh));go.transform.SetParent(p,false);go.transform.localPosition=pos;go.transform.localRotation=Quaternion.identity;var tm=go.GetComponent<TextMesh>();tm.text=n;tm.font=AssetDatabase.LoadAssetAtPath<Font>("Assets/Fonts/BMJUA_ttf.ttf");tm.fontSize=size;tm.characterSize=scale;tm.anchor=TextAnchor.MiddleCenter;tm.color=new Color(1,.76f,.43f);go.GetComponent<Renderer>().sharedMaterial=tm.font.material;}
 static void Run(){var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.path!="Assets/Scenes/JJinCity.unity")throw new Exception("JJinCity must be active to preserve current edits.");var marker=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).FirstOrDefault(t=>t.name=="Weapon_Shop");if(marker==null)throw new Exception("Weapon_Shop missing");if(!EditorSceneManager.SaveScene(s,"Temp/JJinCity-before-weapon-shop.unity",true))throw new Exception("Backup failed");
 Directory.CreateDirectory(Art);Directory.CreateDirectory(Res);AssetDatabase.Refresh();wood=Mat("Oak",new Color(.45f,.26f,.12f));metal=Mat("Steel",new Color(.25f,.31f,.34f));dark=Mat("Charcoal",new Color(.055f,.075f,.09f));orange=Mat("Safety orange",new Color(.91f,.36f,.08f));cream=Mat("Concrete",new Color(.65f,.63f,.54f));blue=Mat("Tuna blue",new Color(.10f,.31f,.42f));ice=Mat("Frost",new Color(.69f,.84f,.86f));red=Mat("Brick terracotta",new Color(.48f,.19f,.12f));skin=Mat("Merchant skin",new Color(.59f,.39f,.25f));Models();
 var prior=marker.Find("Mok Weapon Shop");if(prior!=null)UnityEngine.Object.DestroyImmediate(prior.gameObject);foreach(var r in marker.GetComponents<Renderer>())r.enabled=false;foreach(var c in marker.GetComponents<Collider>())c.enabled=false;
 var root=new GameObject("Mok Weapon Shop");root.transform.SetParent(marker,false);root.transform.localScale=new Vector3(1/marker.lossyScale.x,1/marker.lossyScale.y,1/marker.lossyScale.z);var t=root.transform;
 Part(t,"Floor",new Vector3(0,.04f,0),new Vector3(5,.08f,3.5f),cream,solid:true);Part(t,"Rear wall",new Vector3(0,1.5f,1.6f),new Vector3(5,3,.2f),dark,solid:true);for(int i=-1;i<=1;i+=2){Part(t,"Side wall",new Vector3(i*2.4f,1.5f,.1f),new Vector3(.2f,3,3.2f),metal,solid:true);Part(t,"Front column",new Vector3(i*2.15f,1.4f,-1.45f),new Vector3(.15f,2.8f,.15f),orange,solid:true);}
 Part(t,"Roof",new Vector3(0,3.05f,0),new Vector3(5.3f,.18f,3.8f),metal,solid:true);Part(t,"Sign fascia",new Vector3(0,2.65f,-1.68f),new Vector3(4.8f,.6f,.13f),dark,solid:true);Text(t,"골목 무기점",new Vector3(0,2.67f,-1.76f),64,.065f);
 Part(t,"Counter",new Vector3(0,.6f,-.25f),new Vector3(3.8f,1.1f,.75f),wood,solid:true);Part(t,"Countertop",new Vector3(0,1.18f,-.25f),new Vector3(4,.12f,.9f),metal,solid:true);Part(t,"Pegboard",new Vector3(0,1.65f,1.43f),new Vector3(4,.95f,.08f),wood);for(int i=0;i<4;i++){var display=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Res+((WeaponKind)i)+".prefab"));display.name="Display "+WeaponCatalog.Names[i];display.transform.SetParent(t,false);display.transform.localPosition=new Vector3(-1.5f+i,1.25f,1.25f);}
 var npc=new GameObject("무기상",typeof(WeaponMerchant));npc.transform.SetParent(t,false);npc.transform.localPosition=new Vector3(.5f,.08f,.65f);npc.transform.localRotation=Quaternion.Euler(0,180,0);npc.layer=13;var capsule=npc.AddComponent<CapsuleCollider>();capsule.center=Vector3.up*.9f;capsule.height=1.8f;capsule.radius=.32f;
 WeaponMerchantModelSetup.ApplyVisual(npc.transform);
 var shopLight=new GameObject("Warm shop light",typeof(Light));shopLight.transform.SetParent(t,false);shopLight.transform.localPosition=new Vector3(0,2.5f,0);var light=shopLight.GetComponent<Light>();light.type=LightType.Point;light.color=new Color(1,.75f,.45f);light.range=6;light.intensity=3;
 foreach(var p in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<PlayerCombat>(true)))if(p.GetComponent<PlayerWeapon>()==null)p.gameObject.AddComponent<PlayerWeapon>();
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText("Temp/Mok-weapon-build.txt","PASS: Saved 4 weapon prefabs and shop at "+marker.position+"; current scene backed up.");Selection.activeGameObject=root;if(SceneView.lastActiveSceneView!=null)SceneView.lastActiveSceneView.Frame(new Bounds(marker.position+Vector3.up*1.5f,Vector3.one*8),false);
 }
}
